const input = $json.data ?? $json;
const text = (value) => typeof value === 'string' && value.trim() ? value.trim() : undefined;
const date = (value) => { const valueText = text(value); return valueText && /^\d{4}-\d{2}-\d{2}$/.test(valueText) ? valueText : undefined; };
const item = (row, title, dateValue, weekday, details, subject, itemTime) => { const safeTitle = text(title); if (!safeTitle) return undefined; return { ...(date(dateValue) ? { date: date(dateValue) } : {}), ...(text(weekday) ? { weekday: text(weekday) } : {}), ...(text(itemTime) ? { time: text(itemTime) } : {}), title: safeTitle, ...(text(details) ? { details: text(details) } : {}), ...(text(subject) ? { subject: text(subject) } : {}) }; };
const sortRows = (a, b) => `${a.date ?? '9999-99-99'}T${a.time ?? '99:99'}`.localeCompare(`${b.date ?? '9999-99-99'}T${b.time ?? '99:99'}`);
const events = (input.events ?? []).flatMap(row => { const value = item(row, row.title, row.event_date, row.date_text, row.details, undefined, row.start_time); return value ? [value] : []; }).sort(sortRows);
const reminders = (input.reminders ?? []).flatMap(row => { const value = item(row, row.reminder, row.reminder_date, row.date_text, row.evidence_text); return value ? [value] : []; }).sort(sortRows);
const homework = (input.homework ?? []).flatMap(row => { const value = item(row, row.task, row.due_date, row.due_date_text, row.evidence_text, row.subject); return value ? [value] : []; }).sort(sortRows);
const school_schedule = (input.schedule ?? []).flatMap(row => { const start = text(row.start_time); const end = text(row.end_time); const value = item(row, 'Skole', undefined, row.weekday, undefined, undefined, start && end ? `${start}–${end}` : start); return value ? [value] : []; });
const topics = (input.topics ?? []).flatMap(row => { const subject = text(row.subject); const topic = text(row.topic); return subject && topic ? [`${subject}: ${topic}`] : [topic ?? subject].filter(Boolean); });
const messages = (input.messages ?? []).flatMap(row => { const value = text(row.message); return value ? [value] : []; });
const parts = [events.length ? `${events.length} ${events.length === 1 ? 'avtale' : 'avtaler'}` : '', homework.length ? `${homework.length} ${homework.length === 1 ? 'lekse' : 'lekser'}` : '', reminders.length ? `${reminders.length} ${reminders.length === 1 ? 'påminnelse' : 'påminnelser'}` : ''].filter(Boolean);
const attributes = { summary: parts.length ? `${parts.length > 1 ? `${parts.slice(0, -1).join(', ')} og ${parts.at(-1)}` : parts[0]} denne uken.` : '', ...(date(input.plan?.plan_week_start) ? { week_start: date(input.plan.plan_week_start) } : {}), ...(text(input.plan?.plan_week_end) ? { week_end: text(input.plan.plan_week_end) } : {}), ...(text(input.plan?.created_at) ? { source_updated_at: text(input.plan.created_at) } : {}), ...(typeof input.plan?.weekly_plan_id === 'string' || typeof input.plan?.weekly_plan_id === 'number' ? { plan_id: input.plan.weekly_plan_id } : {}), events, reminders, homework, school_schedule, topics, messages };
return [{ json: { state: text(input.plan?.title) ?? 'Ukjent', attributes } }];
